const DiscCtx = createContext(familias[0].disc);
export const useDisc = () => useContext(DiscCtx);

// Estilos partilhados pelas páginas
export const btn = 'rounded-lg border px-4 py-1.5 text-sm font-medium transition';
export const ativo = 'border-(--accent) bg-(--accent) text-(--accent-fg)';
export const inativo = 'border-(--line) bg-white text-(--ink) hover:bg-(--soft)';
export const card = 'bg-white border-r border-(--line) last:border-r-0';
export const tint = (cor: string, pct = 16) => `color-mix(in srgb, ${cor} ${pct}%, white)`;

const nav = [
  { nome: 'Horário', href: '/', icon: Icons.calendar },
  { nome: 'Alunos', href: '/alunos', icon: Icons.teams },
  { nome: 'Pagamentos', href: '/pagamentos', icon: Icons.billing },
  { nome: 'Mensagens', href: '/mensagens', icon: Icons.chat }
];

export default function Shell({ children }: { children: React.ReactNode }) {
  const [fi, setFi] = useState(0);
  const [si, setSi] = useState(0);
  const [temaAberto, setTemaAberto] = useState(false);
  const [aberta, setAberta] = useState(false);
  const path = usePathname();
  const router = useRouter();
  const conteudo = useRef<HTMLDivElement>(null);
  const fantasma = useRef<HTMLDivElement>(null);

  // Tira uma "fotografia" da página atual e desvanece-a por cima da nova
  const crossfade = () => {
    const atual = conteudo.current;
    const alvo = fantasma.current;
    if (!atual || !alvo) return;
    const copia = atual.cloneNode(true) as HTMLElement;
    copia.removeAttribute('style');
    copia.style.cssText = 'position:absolute;inset:0;display:flex;background:white';
    alvo.replaceChildren(copia);
  };

  // Quando a nova página chega, a cópia da anterior desvanece enquanto a nova entra
  useEffect(() => {
    const copia = fantasma.current?.firstElementChild as HTMLElement | null;
    if (!copia) return;
    copia
      .animate(
        [
          { opacity: 1, filter: 'blur(0)', transform: 'scale(1)' },
          { opacity: 0, filter: 'blur(6px)', transform: 'scale(1.006)' }
        ],
        { duration: 380, easing: 'cubic-bezier(0.4, 0, 0.2, 1)', fill: 'forwards' }
      )
      .finished.then(() => copia.remove());
  }, [path]);
  const familia = familias[fi];
  const sub = familia.subs[si];

  return (
    <DiscCtx.Provider value={familia.disc}>
      <div
        style={sub.vars as CSSProperties}
        className='flex h-screen bg-white text-(--ink) transition-colors'
      >
        <aside
          className={cn(
            'flex shrink-0 flex-col gap-2 overflow-hidden bg-(--rail) px-3 py-4 transition-[width] duration-300 ease-in-out',
            aberta ? 'w-52' : 'w-16'
          )}
        >
          <button
            onClick={() => setAberta((a) => !a)}
            title={aberta ? 'Recolher' : 'Expandir'}
            className='mb-2 flex items-center gap-3 text-left'
          >
            <Logo className='size-10 shrink-0' />
            <span
              className={cn(
                'font-bold whitespace-nowrap text-(--dot) transition-opacity duration-200',
                aberta ? 'opacity-100 delay-150' : 'opacity-0'
              )}
            >
              Lousa
            </span>
          </button>
          {nav.map((n) => {
            const atual = path === n.href;
            return (
              <Link
                key={n.href}
                href={n.href}
                title={n.nome}
                onClick={(e) => {
                  if (atual) return e.preventDefault();
                  e.preventDefault();
                  crossfade();
                  router.push(n.href);
                }}
                className={cn(
                  'flex items-center gap-3 rounded-xl px-2 py-2 transition-colors hover:bg-white/10',
                  atual && 'bg-white/15'
                )}
              >
                <n.icon
                  className={cn(
                    'size-6 shrink-0 text-(--dot) transition-opacity',
                    !atual && 'opacity-60'
                  )}
                  stroke={atual ? 2.2 : 1.8}
                />
                <span
                  className={cn(
                    'text-sm font-medium whitespace-nowrap text-(--dot) transition-all duration-200',
                    aberta ? 'translate-x-0 opacity-100 delay-150' : '-translate-x-2 opacity-0'
                  )}
                >
                  {n.nome}
                </span>
              </Link>
            );
          })}
          <button
            onClick={() => setAberta((a) => !a)}
            title={aberta ? 'Recolher' : 'Expandir'}
            className='mt-auto flex size-10 items-center justify-center rounded-xl text-lg text-(--dot) transition-colors hover:bg-white/10'
          >
            <Icons.chevronsRight
              className={cn('size-5 transition-transform duration-300', aberta && 'rotate-180')}
            />
          </button>
        </aside>

        <style>{`
          @keyframes page-in {
            from { opacity: 0; filter: blur(4px); transform: scale(0.994); }
            to { opacity: 1; filter: blur(0); transform: none; }
          }
        `}</style>
        <div className='relative flex min-w-0 flex-1'>
          <div
            key={path}
            ref={conteudo}
            className='flex min-w-0 flex-1'
            style={{ animation: 'page-in 420ms cubic-bezier(0.22, 1, 0.36, 1) both' }}
          >
            {children}
          </div>
          {/* cópia da página anterior, que desvanece por cima da nova (crossfade) */}
          <div ref={fantasma} className='pointer-events-none absolute inset-0 z-10' />
        </div>

        {/* Seletor de tema (família) e sub-tema */}
        <div className='fixed right-5 bottom-5 z-50 flex flex-col items-end gap-2'>
          <div
            className={cn(
              'w-72 origin-bottom-right rounded-2xl border border-(--line) bg-white p-3 shadow-2xl transition-all duration-200',
              temaAberto ? 'scale-100 opacity-100' : 'pointer-events-none scale-95 opacity-0'
            )}
          >
            <div className='mb-2 px-1 text-xs font-semibold tracking-wide uppercase opacity-60'>Tema</div>
            <ul className='space-y-1'>
              {familias.map((fm, i) => (
                <li
                  key={fm.nome}
                  className={cn(
                    'flex items-center justify-between rounded-xl px-2 py-1.5',
                    fi === i && 'bg-(--soft)'
                  )}
                >
                  <span className='text-sm font-medium'>{fm.nome}</span>
                  <span className='flex gap-1.5'>
                    {fm.subs.map((sb, j) => {
                      const sel = fi === i && si === j;
                      return (
                        <button
                          key={sb.nome}
                          title={`${fm.nome} · ${sb.nome}`}
                          onClick={() => {
                            setFi(i);
                            setSi(j);
                          }}
                          style={{
                            background: `linear-gradient(135deg, ${sb.vars['--rail']} 50%, ${sb.vars['--accent']} 50%)`
                          }}
                          className={cn(
                            'size-6 rounded-full ring-offset-2 transition hover:scale-110',
                            sel ? 'ring-2 ring-(--ink)' : 'ring-1 ring-black/10'
                          )}
                        />
                      );
                    })}
                  </span>
                </li>
              ))}
            </ul>
          </div>
          <button
            onClick={() => setTemaAberto((o) => !o)}
            className='flex items-center gap-2 rounded-full border border-(--line) bg-white py-1.5 pr-4 pl-1.5 text-sm font-medium shadow-lg transition hover:shadow-xl'
          >
            <span
              className='size-7 rounded-full'
              style={{
                background: `linear-gradient(135deg, ${sub.vars['--rail']} 50%, ${sub.vars['--accent']} 50%)`
              }}
            />
            {familia.nome} · {sub.nome}
          </button>
        </div>

      </div>
    </DiscCtx.Provider>
  );
}

export function PageCard({
  titulo,
  acoes,
  children
}: {
  titulo: string;
  acoes?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <main className={cn(card, 'flex min-w-0 flex-1 flex-col overflow-hidden')}>
      <header className='flex items-center justify-between gap-3 px-6 pt-5 pb-3'>
        <h1 className='text-3xl font-extrabold'>{titulo}</h1>
        {acoes}
      </header>
      {children}
    </main>
  );
}

